# owner: platform
"""Find the stretches of opening hours nobody covers."""

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _holes(merged, opening):
    holes, cursor = [], opening.start
    for span in merged:
        if span.start > cursor:
            holes.append(Span(cursor, span.start))
        cursor = span.end
    return holes, cursor


def _check_inside(worked, opening):
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(f"outside opening hours: {span}")


# ---
def find_gaps(worked, opening):
    """Label each uncovered stretch, e.g. gap 12:00-13:00 (60 min)."""
    merged = merge_spans(worked)
    _check_inside(merged, opening)
    holes, cursor = _holes(merged, opening)
    if cursor < opening.end:
        holes.append(Span(cursor, opening.end))
    return [
        f"gap {format_span(hole)} ({hole.minutes} min)"
        for hole in holes
    ]
